"""guild-build's facts part (DAR v2, spec v0.3 section 4.4): what the build record shows, generated by code beside the
supervisor and never chased. MC's own update is the other part (publish_update_v1, written by the portal).

- **checkins:** how many supervisor check-ins ran that day, and the newest at or before its end
  (``guild.supervision_checkins``).
- **build_log:** from ``build_queue.json`` (``GUILD_QUEUE_PATH``, read-only): items in build and blocked or in rework
  **as read at source_checked_at**, and items moved to done during that day.
- **snapshot:** ``not_available_here`` until the harness runs in production.

A source that can't be read is ``unavailable`` with nulls, and the observation is then partial. When neither source
can be read it is unreadable. ``count`` is the items done that day; build events aren't itemised in 1.2.

    python -m services.supervisor.activity_facts --final [--date YYYY-MM-DD]
"""
from __future__ import annotations

import argparse
import json
import os
import sys
from typing import Callable

from core.activity import config
from core.activity.writer import day_bounds, iso, local_moment, today, yesterday

DOMAIN, PART, METRIC, SERVICE = "guild-build", "facts", "build_facts", "minimoi-supervisor"


def facts_writer(environ=os.environ):
    return config.writer_from_environ(domain=DOMAIN, part=PART, metric=METRIC, service=SERVICE, environ=environ)


def _done_during(item: dict, start, end) -> bool:
    moment = local_moment(item.get("last_transition_at"))
    return item.get("status") == "done" and moment is not None and start <= moment <= end


def observe(local_date: str, *, checkins_between: Callable, queue_items: Callable[[], list]) -> tuple[dict, bool]:
    """(detail, every source read)."""
    start, end = day_bounds(local_date)
    try:
        row = checkins_between(start, end) or {}
        last = row.get("last_at")
        checkins = {"state": "ok", "count": int(row.get("count") or 0),
                    "last_at": iso(last.astimezone(start.tzinfo)) if last else None}
    except Exception:                                       # noqa: BLE001 - a source failure is reported, not raised
        checkins = {"state": "unavailable", "count": None, "last_at": None}
    try:
        items = queue_items()
        build_log = {"state": "ok", "in_build": sum(1 for i in items if i.get("status") == "in_build"),
                     "blocked": sum(1 for i in items if i.get("status") in ("blocked", "rework")),
                     "done_today": sum(1 for i in items if _done_during(i, start, end))}
    except Exception:                                       # noqa: BLE001
        build_log = {"state": "unavailable", "in_build": None, "blocked": None, "done_today": None}
    detail = {"checkins": checkins, "build_log": build_log, "snapshot": {"state": "not_available_here"}}
    return detail, checkins["state"] == "ok" and build_log["state"] == "ok"


def publish(local_date: str, *, final: bool, checkins_between: Callable, queue_path: str | None,
            environ=os.environ):
    """One pass; None when off or failed. Never raises."""
    writer = facts_writer(environ)
    if writer is None:
        return None

    def queue_items():
        from domains.guild.queue_store import QueueStore
        return QueueStore(queue_path).read_items()

    detail, whole = observe(local_date, checkins_between=checkins_between, queue_items=queue_items)
    if detail["checkins"]["state"] != "ok" and detail["build_log"]["state"] != "ok":
        return writer.publish_quietly(local_date, state="unreadable", error="build_sources_unreadable", detail=detail)
    complete = final and whole
    return writer.publish_quietly(local_date, state="complete" if complete else "partial", items=[],
                                  count=detail["build_log"]["done_today"] or 0, final=complete, detail=detail,
                                  covers_to=None if final else writer.now())


def after_checkin(store, environ=os.environ) -> None:
    """Called after each supervisor check-in: today's facts so far. Never raises."""
    try:
        publish(today(), final=False, checkins_between=store.checkins_between,
                queue_path=environ.get("GUILD_QUEUE_PATH"), environ=environ)
    except Exception:                                       # noqa: BLE001 - never fail the supervisor's loop
        pass


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Publish guild-build's activity facts (spec v0.3 section 4.4).")
    parser.add_argument("--final", action="store_true", help="the batch-window pass: the whole day, final")
    parser.add_argument("--date", help="the local date (America/Chicago); default yesterday with --final, else today")
    args = parser.parse_args(argv)
    import psycopg2
    from core.supervision.store import Store
    dsn = os.environ["DATABASE_URL"]
    store = Store(lambda: psycopg2.connect(dsn, connect_timeout=5, options="-c statement_timeout=10000"))
    local_date = args.date or (yesterday() if args.final else today())
    record = publish(local_date, final=args.final, checkins_between=store.checkins_between,
                     queue_path=os.environ.get("GUILD_QUEUE_PATH"))
    print(json.dumps({"local_date": local_date, "published": record is not None,
                      "state": record["observation"]["state"] if record else None}))
    return 0 if record is not None else 1


if __name__ == "__main__":
    sys.exit(main())
